SELECT psr.* FROM publisher_share_review psr LEFT JOIN publisher_task pt ON psr.task_id = pt.task_id LEFT JOIN sys_user u ON psr.created_by = u.user_id WHERE psr.deleted = 0
AND psr.task_id = #{req.taskId}
AND pt.task_name LIKE CONCAT('%', #{req.taskName}, '%')
AND psr.review_status_id = #{req.reviewStatus}
AND psr.created_by = #{req.userId}
AND u.wechat_nickname LIKE CONCAT('%', #{req.wechatNickname}, '%')
ORDER BY psr.created_time DESC

